  vid uuid; aid uuid; a jsonb; i jsonb; n int := 0; m int;
begin
  if exists (select 1 from public.vehicles where name = d->'vehicle'->>'name') then
    raise notice 'GW San ist schon vorhanden, nichts getan';
    return;
  end if;
  insert into public.vehicles (name, type, notes, photo_path, sort)
  values (d->'vehicle'->>'name', d->'vehicle'->>'type', d->'vehicle'->>'notes', d->>'photo', 10)
  returning id into vid;
  for a in select * from jsonb_array_elements(d->'areas') loop
    n := n + 1; m := 0;
    insert into public.areas (vehicle_id, name, x, y, sort)
    values (vid, a->>'name', (a->>'x')::numeric, (a->>'y')::numeric, n)
    returning id into aid;
    for i in select * from jsonb_array_elements(a->'items') loop
      m := m + 1;
      insert into public.items (area_id, name, qty, note, sort)
      values (aid, i->>'name', (i->>'qty')::int, nullif(i->>'note',''), m);
    end loop;
  end loop;
end
$gw$;
